1	package wallet
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"sync"
8		"time"
9	)
10	
11	// Wallet 是进程内的智能钱包。
12	//
13	// 所有方法都可被多个 goroutine 并发调用；每一次申请、结算或取消都在
14	// 同一把锁内原子完成，因此余额与共享累计额度不会被超扣，同一请求也
15	// 只会产生一个终态。状态仅在当前 Wallet 实例的生命周期内保留。
16	type Wallet struct {
17		mu sync.Mutex
18	
19		// now 可在同包测试中替换，默认使用 time.Now。
20		now func() time.Time
21	
22		accounts map[string]*account
23		sessions map[string]*session
24		policies map[string]*policy
25		// requests 以“使用账户编号 + 请求编号”为键，实现按使用账户的幂等。
26		requests map[requestKey]*request
27		ledger   []LedgerEntry
28	}
29	
30	type account struct {
31		id        string
32		available int64
33		reserved  int64
34		createdAt time.Time
35	}
36	
37	type session struct {
38		id        string
39		accountID string
40		deviceID  string
41		expiresAt time.Time
42		revoked   bool
43		createdAt time.Time
44	}
45	
46	type policy struct {
47		id                string
48		payerAccountID    string
49		allowedAccounts   map[string]struct{}
50		operation         string
51		payee             string
52		startsAt          time.Time
53		endsAt            time.Time
54		maxPerRequest     int64
55		maxTotal          int64
56		approvalThreshold int64
57		approvalWait      time.Duration
58		// maxReserveDuration 为最长预留时长；零表示关闭预留超时。
59		maxReserveDuration time.Duration
60		reservedTotal      int64
61		spentTotal         int64
62	
63		deactivated          bool
64		deactivatedAt        time.Time
65		deactivatorAccountID string
66		deactivateReason     string
67	}
68	
69	type request struct {
70		policyID       string
71		requestID      string
72		accountID      string
73		payerAccountID string
74		sessionID      string
75		operation      string
76		payee          string
77		estimatedFee   int64
78		actualFee      int64
79		state          RequestState
80		createdAt      time.Time
81		settledAt      time.Time
82		waitDeadline   time.Time
83		// reservedAt 为费用实际预留完成的时刻（直接受理或批准成功的时刻）。
84		reservedAt time.Time
85		// reserveDuration 为预留时适用的最长预留时长快照；零表示未启用超时。
86		reserveDuration time.Duration
87		// reserveDeadline 为预留截止时刻（reservedAt + reserveDuration）。
88		reserveDeadline time.Time
89		// reserveExpiredAt 为超时释放时间；惰性处理时记录的仍是截止时刻本身。
90		reserveExpiredAt  time.Time
91		decidedAt         time.Time
92		approverAccountID string
93		rejectReason      string
94	}
95	
96	type requestKey struct {
97		accountID string
98		requestID string
99	}
100	
101	// New 创建一个空钱包。
102	func New() *Wallet {
103		return &Wallet{
104			now:      time.Now,
105			accounts: make(map[string]*account),
106			sessions: make(map[string]*session),
107			policies: make(map[string]*policy),
108			requests: make(map[requestKey]*request),
109		}
110	}
111	
112	// CreateAccount 创建具有唯一编号和初始代付余额的账户。
113	//
114	// 金额为最小货币单位的整数；初始余额为负或编号重复时返回错误，
115	// 且不会改动任何已有资金记录。
116	func (w *Wallet) CreateAccount(id string, initialBalance int64) (AccountView, error) {
117		if id == "" {
118			return AccountView{}, ErrEmptyAccountID
119		}
120		if initialBalance < 0 {
121			return AccountView{}, fmt.Errorf("%w: initial balance must not be negative", ErrInvalidAmount)
122		}
123	
124		w.mu.Lock()
125		defer w.mu.Unlock()
126	
127		if _, ok := w.accounts[id]; ok {
128			return AccountView{}, fmt.Errorf("%w: %s", ErrAccountExists, id)
129		}
130		now := w.now()
131		acc := &account{id: id, available: initialBalance, createdAt: now}
132		w.accounts[id] = acc
133		return acc.view(), nil
134	}
135	
136	// Account 查询账户视图；账户不存在时返回 ErrAccountNotFound。
137	// 查询时已到期的预留会先被自动释放，因此视图反映最新的可用/预留余额。
138	func (w *Wallet) Account(id string) (AccountView, error) {
139		w.mu.Lock()
140		defer w.mu.Unlock()
141	
142		acc, ok := w.accounts[id]
143		if !ok {
144			return AccountView{}, fmt.Errorf("%w: %s", ErrAccountNotFound, id)
145		}
146		w.expireReservationsLocked(w.now())
147		return acc.view(), nil
148	}
149	
150	// Balance 查询账户的可用余额与预留余额。
151	func (w *Wallet) Balance(id string) (Balances, error) {
152		view, err := w.Account(id)
153		if err != nil {
154			return Balances{}, err
155		}
156		return view.Balances, nil
157	}
158	
159	// CreateSession 为账户创建一个绑定设备、带到期时间的会话。
160	//
161	// 会话编号全局唯一；账户必须存在。
162	func (w *Wallet) CreateSession(id, accountID, deviceID string, expiresAt time.Time) (SessionView, error) {
163		if id == "" || accountID == "" || deviceID == "" {
164			return SessionView{}, fmt.Errorf("%w: session id, account id and device id are required", ErrInvalidArgument)
165		}
166	
167		w.mu.Lock()
168		defer w.mu.Unlock()
169	
170		if _, ok := w.accounts[accountID]; !ok {
171			return SessionView{}, fmt.Errorf("%w: %s", ErrAccountNotFound, accountID)
172		}
173		if _, ok := w.sessions[id]; ok {
174			return SessionView{}, fmt.Errorf("%w: %s", ErrSessionExists, id)
175		}
176		now := w.now()
177		sess := &session{
178			id:        id,
179			accountID: accountID,
180			deviceID:  deviceID,
181			expiresAt: expiresAt,
182			createdAt: now,
183		}
184		w.sessions[id] = sess
185		return sess.view(), nil
186	}
187	
188	// RevokeSession 主动吊销会话。会话不存在返回 ErrSessionNotFound；已经到期
189	// 的会话也允许吊销；重复吊销视为成功且不重复留痕。吊销后不再受理该会话
190	// 的新申请。
191	//
192	// 吊销瞬间按各请求自身的等待截止时间分别结清该会话仍在待审批的请求：
193	// 当前时刻严格早于截止时间的进入拒绝终态并说明申请会话已被吊销，决定
194	// 时间为吊销时刻；当前时刻等于或晚于截止时间（等待时长耗尽、策略结束
195	// 或申请会话到期先发生）的进入过期终态，不带吊销拒绝原因、不填写审批
196	// 账户，提交时间与等待截止时间保持不变。终态结果只取决于申请自身的
197	// 期限，不因吊销前是否被查询过而不同；先前已进入终态的请求保留原决定
198	// 信息与历史记录。
199	//
200	// 两类处理都不冻结费用：不改变出资余额、策略预留总额和已花费总额，也不
201	// 生成退款、扣减或预留记录。已预留请求继续按原规则结算、取消或等待自身
202	// 预留超时，吊销不提前释放费用；其他会话的申请不受影响。
203	func (w *Wallet) RevokeSession(id string) error {
204		w.mu.Lock()
205		defer w.mu.Unlock()
206	
207		sess, ok := w.sessions[id]
208		if !ok {
209			return fmt.Errorf("%w: %s", ErrSessionNotFound, id)
210		}
211		if sess.revoked {
212			return nil
213		}
214		sess.revoked = true
215		now := w.now()
216		reason := "application session revoked before approval"
217	
218		pending := make([]*request, 0)
219		for _, req := range w.requests {
220			if req.state == RequestPendingApproval && req.sessionID == sess.id {
221				pending = append(pending, req)
222			}
223		}
224		w.settlePendingLocked(pending, now, func(req *request) {
225			// 未到等待期限：随会话吊销进入拒绝终态，不填写审批账户。
226			req.state = RequestRejected
227			req.rejectReason = reason
228			req.decidedAt = now
229			w.ledger = append(w.ledger, LedgerEntry{
230				Kind:      LedgerRejection,
231				AccountID: req.accountID,
232				RequestID: req.requestID,
233				Reason:    reason,
234				At:        now,
235			})
236		})
237		return nil
238	}
239	
240	// Session 查询会话视图。
241	func (w *Wallet) Session(id string) (SessionView, error) {
242		w.mu.Lock()
243		defer w.mu.Unlock()
244	
245		sess, ok := w.sessions[id]
246		if !ok {
247			return SessionView{}, fmt.Errorf("%w: %s", ErrSessionNotFound, id)
248		}
249		return sess.view(), nil
250	}
251	
252	// SavePolicy 保存（创建）一条代付策略。
253	//
254	// 出资账户和所有使用账户必须存在，限额必须为正，开始时间必须严格早于
255	// 结束时间，编号不得重复，否则拒绝保存并返回包装了具体原因的错误。
256	func (w *Wallet) SavePolicy(spec PolicySpec) error {
257		if spec.ID == "" {
258			return fmt.Errorf("%w: policy id is required", ErrPolicyInvalid)
259		}
260		if spec.Operation == "" || spec.Payee == "" {
261			return fmt.Errorf("%w: operation and payee are required", ErrPolicyInvalid)
262		}
263		if spec.MaxPerRequest <= 0 || spec.MaxTotal <= 0 {
264			return fmt.Errorf("%w: limits must be positive", ErrPolicyInvalid)
265		}
266		// 审批门槛：零表示关闭；不得为负，不得超过单次上限；开启时等待时长必须为正。
267		if spec.ApprovalThreshold < 0 {
268			return fmt.Errorf("%w: approval threshold must not be negative", ErrPolicyInvalid)
269		}
270		if spec.ApprovalThreshold > 0 {
271			if spec.ApprovalThreshold > spec.MaxPerRequest {
272				return fmt.Errorf("%w: approval threshold %d exceeds per-request limit %d", ErrPolicyInvalid, spec.ApprovalThreshold, spec.MaxPerRequest)
273			}
274			if spec.ApprovalWait <= 0 {
275				return fmt.Errorf("%w: approval wait must be positive when approval is enabled", ErrPolicyInvalid)
276			}
277		}
278		// 最长预留时长：零表示关闭预留超时（保持既有行为）；不得为负。
279		if spec.MaxReserveDuration < 0 {
280			return fmt.Errorf("%w: max reserve duration must not be negative", ErrPolicyInvalid)
281		}
282		if !spec.StartsAt.Before(spec.EndsAt) {
283			return fmt.Errorf("%w: starts-at must be before ends-at", ErrPolicyInvalid)
284		}
285		if spec.PayerAccountID == "" || len(spec.AllowedAccountIDs) == 0 {
286			return fmt.Errorf("%w: payer account and at least one allowed account are required", ErrPolicyInvalid)
287		}
288	
289		w.mu.Lock()
290		defer w.mu.Unlock()
291	
292		if _, ok := w.policies[spec.ID]; ok {
293			return fmt.Errorf("%w: %s", ErrPolicyExists, spec.ID)
294		}
295		if _, ok := w.accounts[spec.PayerAccountID]; !ok {
296			return fmt.Errorf("%w: payer account %q: %w", ErrPolicyInvalid, spec.PayerAccountID, ErrAccountNotFound)
297		}
298		allowed := make(map[string]struct{}, len(spec.AllowedAccountIDs))
299		for _, id := range spec.AllowedAccountIDs {
300			if _, ok := w.accounts[id]; !ok {
301				return fmt.Errorf("%w: allowed account %q: %w", ErrPolicyInvalid, id, ErrAccountNotFound)
302			}
303			allowed[id] = struct{}{}
304		}
305	
306		w.policies[spec.ID] = &policy{
307			id:                 spec.ID,
308			payerAccountID:     spec.PayerAccountID,
309			allowedAccounts:    allowed,
310			operation:          spec.Operation,
311			payee:              spec.Payee,
312			startsAt:           spec.StartsAt,
313			endsAt:             spec.EndsAt,
314			maxPerRequest:      spec.MaxPerRequest,
315			maxTotal:           spec.MaxTotal,
316			approvalThreshold:  spec.ApprovalThreshold,
317			approvalWait:       spec.ApprovalWait,
318			maxReserveDuration: spec.MaxReserveDuration,
319		}
320		return nil
321	}
322	
323	// Policy 查询策略视图，含当前预留中与已结算的累计金额。查询时已到期的
324	// 预留会先被自动释放，ReservedTotal 因而反映释放后的结果。
325	func (w *Wallet) Policy(id string) (PolicyView, error) {
326		w.mu.Lock()
327		defer w.mu.Unlock()
328	
329		p, ok := w.policies[id]
330		if !ok {
331			return PolicyView{}, fmt.Errorf("%w: %s", ErrPolicyNotFound, id)
332		}
333		w.expireReservationsLocked(w.now())
334		return p.view(), nil
335	}
336	
337	// DeactivatePolicy 由出资账户主动停用一条代付策略，立即停止该策略继续
338	// 受理代付。停用不可撤销。
339	//
340	// 必须使用该策略出资账户绑定当前设备的有效会话：会话不存在、不属于出资
341	// 账户、设备不符、已吊销或已到期时返回 ErrNotPolicyOwner，不改变策略、
342	// 请求或账本。策略编号、会话编号、设备缺失，或理由去掉首尾空白后为空，
343	// 返回 ErrInvalidArgument。策略不存在返回 ErrPolicyNotFound。保存与比较
344	// 理由均使用去掉首尾空白后的内容。
345	//
346	// 再次停用仍须通过会话校验：理由与首次相同时幂等返回首次结果，理由不同
347	// 返回 ErrConflict；两者都不改写首次停用信息，也不增加账本记录。尚未
348	// 开始或已经结束的策略也允许停用；停用后该编号不能再保存成新策略。
349	//
350	// 停用成功时，该策略下未到等待期限的待审批请求立即转为拒绝终态，拒绝
351	// 信息说明策略被停用并包含停用理由，决定时间为停用时间；已到（含恰到）
352	// 或超过等待期限的待审批请求进入过期终态。两类处理都不冻结余额、不占用
353	// 额度，也不产生退款；其他状态的请求与其他策略不受影响。
354	func (w *Wallet) DeactivatePolicy(policyID, sessionID, deviceID, reason string) (PolicyView, error) {
355		reason = strings.TrimSpace(reason)
356		if policyID == "" || sessionID == "" || deviceID == "" || reason == "" {
357			return PolicyView{}, fmt.Errorf("%w: policy id, session id, device id and reason are required", ErrInvalidArgument)
358		}
359	
360		w.mu.Lock()
361		defer w.mu.Unlock()
362	
363		p, ok := w.policies[policyID]
364		if !ok {
365			return PolicyView{}, fmt.Errorf("%w: %s", ErrPolicyNotFound, policyID)
366		}
367		now := w.now()
368		if err := w.checkPolicyOwnerLocked(p, sessionID, deviceID, now); err != nil {
369			return PolicyView{}, err
370		}
371		// 鉴权通过后先释放已到期预留（停用不缩短任何未到期请求的截止时间）。
372		w.expireReservationsLocked(now)
373	
374		if p.deactivated {
375			// 停用不可撤销：理由相同返回首次结果，理由不同返回冲突，
376			// 均不改写首次信息、不增加账本记录。
377			if p.deactivateReason == reason {
378				return p.view(), nil
379			}
380			return PolicyView{}, fmt.Errorf("%w: policy %s was already deactivated with a different reason", ErrConflict, policyID)
381		}
382	
383		p.deactivated = true
384		p.deactivatedAt = now
385		p.deactivatorAccountID = p.payerAccountID
386		p.deactivateReason = reason
387	
388		w.ledger = append(w.ledger, LedgerEntry{
389			Kind:      LedgerPolicyDeactivation,
390			AccountID: p.payerAccountID,
391			PolicyID:  p.id,
392			Reason:    reason,
393			At:        now,
394		})
395	
396		// 停用瞬间结清该策略全部待审批请求：未到等待期限的随停用立即拒绝，
397		// 已到或超过期限的进入过期终态（不能因未被查询过而变成停用拒绝）。
398		pending := make([]*request, 0)
399		for _, req := range w.requests {
400			if req.policyID == p.id && req.state == RequestPendingApproval {
401				pending = append(pending, req)
402			}
403		}
404		w.settlePendingLocked(pending, now, func(req *request) {
405			msg := fmt.Sprintf("policy %s deactivated by payer: %s", p.id, reason)
406			req.state = RequestRejected
407			req.rejectReason = msg
408			req.decidedAt = now
409			req.approverAccountID = p.payerAccountID
410			w.ledger = append(w.ledger, LedgerEntry{
411				Kind:      LedgerRejection,
412				AccountID: req.accountID,
413				RequestID: req.requestID,
414				Reason:    msg,
415				At:        now,
416			})
417		})
418		return p.view(), nil
419	}
420	
421	// checkPolicyOwnerLocked 在持锁状态下校验停用会话：必须存在、归属策略的
422	// 出资账户、绑定当前设备、未吊销且未到期。任一不满足都返回
423	// ErrNotPolicyOwner，且不改变策略、请求或账本。
424	func (w *Wallet) checkPolicyOwnerLocked(p *policy, sessionID, deviceID string, now time.Time) error {
425		sess, ok := w.sessions[sessionID]
426		if !ok {
427			return fmt.Errorf("%w: session %s", ErrNotPolicyOwner, sessionID)
428		}
429		if sess.accountID != p.payerAccountID {
430			return fmt.Errorf("%w: session %s belongs to account %s, not payer %s", ErrNotPolicyOwner, sess.id, sess.accountID, p.payerAccountID)
431		}
432		if sess.deviceID != deviceID {
433			return fmt.Errorf("%w: session %s is bound to device %s, not %s", ErrNotPolicyOwner, sess.id, sess.deviceID, deviceID)
434		}
435		if sess.revoked {
436			return fmt.Errorf("%w: session %s revoked", ErrNotPolicyOwner, sess.id)
437		}
438		if !now.Before(sess.expiresAt) {
439			return fmt.Errorf("%w: session %s expired at %s", ErrNotPolicyOwner, sess.id, sess.expiresAt.Format(time.RFC3339))
440		}
441		return nil
442	}
443	
444	// Apply 提交一笔代付申请。
445	//
446	// 校验顺序为：申请字段 -> 使用账户 -> 会话（存在性、归属、设备、吊销、
447	// 到期）-> 幂等请求编号 -> 策略授权与额度 -> 出资账户余额。任一环节
448	// 失败都会在账本中留下带具体原因的拒绝记录，不产生任何扣款或预留。
449	//
450	// 同一使用账户以相同请求编号重复申请：策略、操作类型、收款方和预估
451	// 费用一致时直接返回已有请求（不再预留）；任一不同则返回 ErrConflict。
452	func (w *Wallet) Apply(in RequestInput) (RequestView, error) {
453		if in.EstimatedFee <= 0 {
454			return RequestView{}, w.reject(in, fmt.Errorf("%w: estimated fee must be positive", ErrInvalidAmount))
455		}
456		if in.AccountID == "" || in.SessionID == "" || in.DeviceID == "" || in.RequestID == "" || in.PolicyID == "" {
457			return RequestView{}, w.reject(in, fmt.Errorf("%w: account, session, device, policy and request id are required", ErrInvalidArgument))
458		}
459	
460		w.mu.Lock()
461		defer w.mu.Unlock()
462	
463		now := w.now()
464	
465		acc, ok := w.accounts[in.AccountID]
466		if !ok {
467			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrAccountNotFound, in.AccountID))
468		}
469		_ = acc
470	
471		sess, ok := w.sessions[in.SessionID]
472		if !ok {
473			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrSessionNotFound, in.SessionID))
474		}
475		if sess.accountID != in.AccountID {
476			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s belongs to account %s", ErrSessionAccountMismatch, sess.id, sess.accountID))
477		}
478		if sess.deviceID != in.DeviceID {
479			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s is bound to device %s", ErrSessionDeviceMismatch, sess.id, sess.deviceID))
480		}
481		if sess.revoked {
482			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s", ErrSessionRevoked, sess.id))
483		}
484		// 到期时刻及之后一律视为过期：[零值, ExpiresAt) 才有效。
485		if !now.Before(sess.expiresAt) {
486			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s expired at %s", ErrSessionExpired, sess.id, sess.expiresAt.Format(time.RFC3339)))
487		}
488	
489		key := requestKey{accountID: in.AccountID, requestID: in.RequestID}
490		if existing, ok := w.requests[key]; ok {
491			// 待审批到期即过期、已预留到期即自动退回，重复申请看到的应是最新终态。
492			w.refreshPendingLocked(existing, now)
493			w.refreshReservedLocked(existing, now)
494			if existing.policyID == in.PolicyID &&
495				existing.operation == in.Operation &&
496				existing.payee == in.Payee &&
497				existing.estimatedFee == in.EstimatedFee {
498				// 幂等命中：直接返回已有结果，不再预留、不记账。
499				return existing.view(), nil
500			}
501			return RequestView{}, fmt.Errorf("%w: account %s request %s was already submitted with different content", ErrConflict, in.AccountID, in.RequestID)
502		}
503	
504		p, ok := w.policies[in.PolicyID]
505		if !ok {
506			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrPolicyNotFound, in.PolicyID))
507		}
508		// 停用后的策略不再受理新申请；历史请求的幂等查询在上方已先行处理。
509		if p.deactivated {
510			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: policy %s deactivated: %s", ErrPolicyDeactivated, p.id, p.deactivateReason))
511		}
512		if _, ok := p.allowedAccounts[in.AccountID]; !ok {
513			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: account %s is not allowed by policy %s", ErrPolicyDenied, in.AccountID, p.id))
514		}
515		if in.Operation != p.operation {
516			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: operation %q does not match policy %q", ErrPolicyDenied, in.Operation, p.operation))
517		}
518		if in.Payee != p.payee {
519			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payee %q does not match policy %q", ErrPolicyDenied, in.Payee, p.payee))
520		}
521		// 时间窗含开始、不含结束：[StartsAt, EndsAt)。
522		if now.Before(p.startsAt) || !now.Before(p.endsAt) {
523			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: current time %s is outside policy window [%s, %s)", ErrPolicyDenied,
524				now.Format(time.RFC3339), p.startsAt.Format(time.RFC3339), p.endsAt.Format(time.RFC3339)))
525		}
526		if in.EstimatedFee > p.maxPerRequest {
527			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d exceeds per-request limit %d", ErrQuotaExceeded, in.EstimatedFee, p.maxPerRequest))
528		}
529		// 资金与额度检查前释放所有已到期预留（含同一出资账户在其他策略下的
530		// 预留），因此先查余额还是先申请看到的可用金额都一致。
531		w.expireReservationsLocked(now)
532		// 预留中的费用同样占用共享累计额度。
533		if used, exceed := quotaWouldExceedLocked(p, in.EstimatedFee); exceed {
534			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d would exceed shared total limit %d (used %d)",
535				ErrQuotaExceeded, in.EstimatedFee, p.maxTotal, used))
536		}
537	
538		payer, ok := w.accounts[p.payerAccountID]
539		if !ok {
540			// 保存策略时已校验，这里仅作防御。
541			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("payer account %s: %w", p.payerAccountID, ErrAccountNotFound))
542		}
543		if payer.available < in.EstimatedFee {
544			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, in.EstimatedFee))
545		}
546	
547		// 所有硬性检查通过：预估费用严格超过审批门槛的进入待审批，其余直接预留。
548		if p.approvalThreshold > 0 && in.EstimatedFee > p.approvalThreshold {
549			// 待审批不冻结余额、不占用共享累计额度。期限取提交时刻 + 等待时长、
550			// 策略结束时间、申请会话到期时间三者中的最早值。
551			deadline := now.Add(p.approvalWait)
552			if p.endsAt.Before(deadline) {
553				deadline = p.endsAt
554			}
555			if sess.expiresAt.Before(deadline) {
556				deadline = sess.expiresAt
557			}
558			req := &request{
559				policyID:       p.id,
560				requestID:      in.RequestID,
561				accountID:      in.AccountID,
562				payerAccountID: payer.id,
563				sessionID:      sess.id,
564				operation:      in.Operation,
565				payee:          in.Payee,
566				estimatedFee:   in.EstimatedFee,
567				state:          RequestPendingApproval,
568				createdAt:      now,
569				waitDeadline:   deadline,
570			}
571			w.requests[key] = req
572			w.ledger = append(w.ledger, LedgerEntry{
573				Kind:      LedgerPendingApproval,
574				AccountID: in.AccountID,
575				RequestID: in.RequestID,
576				Reason:    "pending approval for large amount",
577				At:        now,
578			})
579			return req.view(), nil
580		}
581	
582		// 所有硬性检查通过且无需审批：直接受理。以提交时刻作为实际预留时刻，
583		// 不填写任何审批决定信息。
584		req := &request{
585			policyID:       p.id,
586			requestID:      in.RequestID,
587			accountID:      in.AccountID,
588			payerAccountID: payer.id,
589			sessionID:      sess.id,
590			operation:      in.Operation,
591			payee:          in.Payee,
592			estimatedFee:   in.EstimatedFee,
593			createdAt:      now,
594		}
595		w.reserveFeeLocked(p, payer, req, now, "reserve estimated fee")
596		w.requests[key] = req
597		return req.view(), nil
598	}
599	
600	// Settle 结算一笔已预留的代付请求。
601	//
602	// actualFee 允许为零但不得为负、不得超过预留的预估费用。结算时扣除
603	// 实际费用并把差额退回可用余额。以相同实际费用重复结算幂等返回，不
604	// 重复记账；不同实际费用返回 ErrConflict。已取消的请求不能结算。
605	func (w *Wallet) Settle(accountID, requestID string, actualFee int64) (RequestView, error) {
606		if actualFee < 0 {
607			return RequestView{}, fmt.Errorf("%w: actual fee must not be negative", ErrInvalidAmount)
608		}
609		w.mu.Lock()
610		defer w.mu.Unlock()
611	
612		req, p, err := w.lookupRequest(accountID, requestID)
613		if err != nil {
614			return RequestView{}, err
615		}
616		now := w.now()
617		w.refreshPendingLocked(req, now)
618		// 已到最长预留时长的预留先自动退回：此后任何结算都不能再扣款。
619		w.refreshReservedLocked(req, now)
620		switch req.state {
621		case RequestSettled:
622			if req.actualFee == actualFee {
623				return req.view(), nil
624			}
625			return RequestView{}, fmt.Errorf("%w: request %s already settled with actual fee %d", ErrConflict, requestID, req.actualFee)
626		case RequestCancelled:
627			return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadyCancelled, requestID)
628		case RequestReservationExpired:
629			// 预留已超时全额退回：传入非负实际费用也返回明确的超时错误，不能扣款。
630			return RequestView{}, fmt.Errorf("%w: request %s reservation expired at %s", ErrReservationExpired, requestID, req.reserveExpiredAt.Format(time.RFC3339))
631		case RequestPendingApproval, RequestRejected, RequestExpired:
632			// 结算只允许处理已预留请求。
633			return RequestView{}, fmt.Errorf("%w: request %s is %v, only reserved requests can be settled", ErrRequestNotReserved, requestID, req.state)
634		}
635	
636		if actualFee > req.estimatedFee {
637			// 拒绝并保留预留。
638			return RequestView{}, fmt.Errorf("%w: actual %d > estimated %d for request %s", ErrSettleTooLarge, actualFee, req.estimatedFee, requestID)
639		}
640	
641		payer := w.accounts[req.payerAccountID]
642		refund := req.estimatedFee - actualFee
643	
644		// 扣除实际费用、退回差额、释放共享额度。
645		payer.reserved -= req.estimatedFee
646		payer.available += refund
647		p.reservedTotal -= req.estimatedFee
648		p.spentTotal += actualFee
649	
650		req.state = RequestSettled
651		req.actualFee = actualFee
652		req.settledAt = now
653	
654		w.ledger = append(w.ledger, LedgerEntry{
655			Kind:      LedgerSettle,
656			AccountID: payer.id,
657			RequestID: requestID,
658			Amount:    actualFee,
659			Reason:    "settle actual fee",
660			At:        now,
661		})
662		if refund > 0 {
663			w.ledger = append(w.ledger, LedgerEntry{
664				Kind:      LedgerRefund,
665				AccountID: payer.id,
666				RequestID: requestID,
667				Amount:    refund,
668				Reason:    "refund estimated-minus-actual fee",
669				At:        now,
670			})
671		}
672		return req.view(), nil
673	}
674	
675	// Cancel 取消一笔尚未结算的代付请求。
676	//
677	// 待审批请求取消后直接进入取消终态，不产生退款（本就没有冻结余额）；
678	// 已预留请求取消后全部预留退回。已结算的请求不能取消；重复取消幂等
679	// 返回，不重复记账。已拒绝或已过期的请求不能取消。
680	func (w *Wallet) Cancel(accountID, requestID string) (RequestView, error) {
681		w.mu.Lock()
682		defer w.mu.Unlock()
683	
684		req, p, err := w.lookupRequest(accountID, requestID)
685		if err != nil {
686			return RequestView{}, err
687		}
688		now := w.now()
689		w.refreshPendingLocked(req, now)
690		// 已到最长预留时长的预留先自动退回。
691		w.refreshReservedLocked(req, now)
692		switch req.state {
693		case RequestCancelled:
694			return req.view(), nil
695		case RequestSettled:
696			return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadySettled, requestID)
697		case RequestReservationExpired:
698			// 预留已超时自动全额退回：取消幂等返回已有超时结果，不重复退回、不留痕。
699			return req.view(), nil
700		case RequestPendingApproval:
701			// 待审批取消：无资金冻结，直接留取消终态。
702			req.state = RequestCancelled
703			req.decidedAt = now
704			w.ledger = append(w.ledger, LedgerEntry{
705				Kind:      LedgerCancellation,
706				AccountID: req.accountID,
707				RequestID: req.requestID,
708				Reason:    "cancel pending-approval request",
709				At:        now,
710			})
711			return req.view(), nil
712		case RequestRejected, RequestExpired:
713			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot cancel", ErrRequestNotReserved, requestID, req.state)
714		}
715	
716		// 已预留：退回全部预留。
717		payer := w.accounts[req.payerAccountID]
718	
719		payer.reserved -= req.estimatedFee
720		payer.available += req.estimatedFee
721		p.reservedTotal -= req.estimatedFee
722	
723		req.state = RequestCancelled
724	
725		w.ledger = append(w.ledger, LedgerEntry{
726			Kind:      LedgerRefund,
727			AccountID: payer.id,
728			RequestID: requestID,
729			Amount:    req.estimatedFee,
730			Reason:    "refund reserved fee on cancel",
731			At:        now,
732		})
733		return req.view(), nil
734	}
735	
736	// Approve 批准一笔待审批的大额代付请求。
737	//
738	// 审批必须使用该策略出资账户绑定当前设备的有效会话；其他账户或无效
739	// 会话返回 ErrNotApprover 无权审批，且不改变请求。批准时再次检查出资
740	// 余额与共享剩余额度，足够才一次性预留全部预估费用并转为已预留；不足
741	// 时返回具体原因，保留待审批状态，期限内可再次批准。
742	//
743	// 已批准并处于预留或结算状态的请求重复批准只返回当前结果，不重复预留；
744	// 已拒绝、过期或取消的请求不能批准。截止时刻及之后不能批准。
745	func (w *Wallet) Approve(accountID, requestID, sessionID, deviceID string) (RequestView, error) {
746		if accountID == "" || requestID == "" || sessionID == "" || deviceID == "" {
747			return RequestView{}, fmt.Errorf("%w: account, request, session and device ids are required", ErrInvalidArgument)
748		}
749		w.mu.Lock()
750		defer w.mu.Unlock()
751	
752		now := w.now()
753		req, p, err := w.lookupRequest(accountID, requestID)
754		if err != nil {
755			return RequestView{}, err
756		}
757		if err := w.checkApproverLocked(req, sessionID, deviceID, now); err != nil {
758			return RequestView{}, err
759		}
760		// 鉴权通过后释放已到期预留（含同一出资账户在其他策略下的预留），使
761		// 批准的余额与额度检查计入退回；因余额或额度不足而失败的批准不会开始
762		// 预留计时。
763		w.expireReservationsLocked(now)
764		w.refreshPendingLocked(req, now)
765		if req.state == RequestExpired {
766			return RequestView{}, fmt.Errorf("%w: approval deadline %s passed", ErrApprovalExpired, req.waitDeadline.Format(time.RFC3339))
767		}
768	
769		switch req.state {
770		case RequestPendingApproval:
771			payer := w.accounts[req.payerAccountID]
772			if payer.available < req.estimatedFee {
773				return RequestView{}, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, req.estimatedFee)
774			}
775			if used, exceed := quotaWouldExceedLocked(p, req.estimatedFee); exceed {
776				return RequestView{}, fmt.Errorf("%w: estimated fee %d would exceed shared total limit %d (used %d)",
777					ErrQuotaExceeded, req.estimatedFee, p.maxTotal, used)
778			}
779			// 一次性完成全部预估费用的预留（资金划转、转已预留、预留记录与从批准
780			// 成功时刻起算的预留计时）；余额或额度不足时已在上方返回，不会走到
781			// 这里，因此失败的批准不会开始计时。
782			w.reserveFeeLocked(p, payer, req, now, "reserve estimated fee on approval")
783			// 批准成功保留原提交时刻与等待截止时刻；决定时间为批准时刻，并记录
784			// 出资账户的批准决定。随后追加使用账户的零金额批准状态记录。
785			req.decidedAt = now
786			req.approverAccountID = payer.id
787			w.ledger = append(w.ledger, LedgerEntry{
788				Kind:      LedgerApproval,
789				AccountID: req.accountID,
790				RequestID: req.requestID,
791				Reason:    "approve large-amount request",
792				At:        now,
793			})
794			return req.view(), nil
795		case RequestReserved, RequestSettled:
796			// 已批准：重复批准幂等返回，不重复预留。
797			return req.view(), nil
798		default:
799			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot approve", ErrRequestNotPending, requestID, req.state)
800		}
801	}
802	
803	// Reject 拒绝一笔待审批的大额代付请求。
804	//
805	// 拒绝必须使用该策略出资账户绑定当前设备的有效会话；其他账户或无效
806	// 会话返回 ErrNotApprover 无权审批，且不改变请求。拒绝理由为空或全为
807	// 空白时返回 ErrInvalidArgument 参数错误，请求保持不变。
808	//
809	// 重复拒绝且理由一致时幂等返回，不重复留痕；理由不同返回 ErrConflict。
810	// 已批准（含预留、结算）、已过期或已取消的请求不能拒绝。
811	func (w *Wallet) Reject(accountID, requestID, sessionID, deviceID, reason string) (RequestView, error) {
812		if strings.TrimSpace(reason) == "" {
813			return RequestView{}, fmt.Errorf("%w: reject reason must not be empty or blank", ErrInvalidArgument)
814		}
815		if accountID == "" || requestID == "" || sessionID == "" || deviceID == "" {
816			return RequestView{}, fmt.Errorf("%w: account, request, session and device ids are required", ErrInvalidArgument)
817		}
818		w.mu.Lock()
819		defer w.mu.Unlock()
820	
821		now := w.now()
822		req, _, err := w.lookupRequest(accountID, requestID)
823		if err != nil {
824			return RequestView{}, err
825		}
826		if err := w.checkApproverLocked(req, sessionID, deviceID, now); err != nil {
827			return RequestView{}, err
828		}
829		w.refreshPendingLocked(req, now)
830	
831		switch req.state {
832		case RequestPendingApproval:
833			req.state = RequestRejected
834			req.rejectReason = reason
835			req.decidedAt = now
836			req.approverAccountID = req.payerAccountID
837	
838			w.ledger = append(w.ledger, LedgerEntry{
839				Kind:      LedgerRejection,
840				AccountID: req.accountID,
841				RequestID: req.requestID,
842				Reason:    reason,
843				At:        now,
844			})
845			return req.view(), nil
846		case RequestRejected:
847			if req.rejectReason == reason {
848				return req.view(), nil
849			}
850			return RequestView{}, fmt.Errorf("%w: request %s already rejected with a different reason", ErrConflict, requestID)
851		default:
852			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot reject", ErrRequestNotPending, requestID, req.state)
853		}
854	}
855	
856	// checkApproverLocked 在持锁状态下校验审批会话：必须存在、归属出资账户、
857	// 绑定当前设备、未吊销且未过期。任一不满足都返回 ErrNotApprover，且不
858	// 改变请求。
859	func (w *Wallet) checkApproverLocked(req *request, sessionID, deviceID string, now time.Time) error {
860		sess, ok := w.sessions[sessionID]
861		if !ok {
862			return fmt.Errorf("%w: session %s", ErrNotApprover, sessionID)
863		}
864		if sess.accountID != req.payerAccountID {
865			return fmt.Errorf("%w: session %s belongs to account %s, not payer %s", ErrNotApprover, sess.id, sess.accountID, req.payerAccountID)
866		}
867		if sess.deviceID != deviceID {
868			return fmt.Errorf("%w: session %s is bound to device %s, not %s", ErrNotApprover, sess.id, sess.deviceID, deviceID)
869		}
870		if sess.revoked {
871			return fmt.Errorf("%w: session %s revoked", ErrNotApprover, sess.id)
872		}
873		if !now.Before(sess.expiresAt) {
874			return fmt.Errorf("%w: session %s expired at %s", ErrNotApprover, sess.id, sess.expiresAt.Format(time.RFC3339))
875		}
876		return nil
877	}
878	
879	// refreshPendingLocked 在持锁状态下检查待审批请求是否已到期限；到期
880	// （含到期时刻）则转为过期终态并记账。必须在持锁状态下调用。
881	func (w *Wallet) refreshPendingLocked(req *request, now time.Time) {
882		if req.state != RequestPendingApproval {
883			return
884		}
885		if now.Before(req.waitDeadline) {
886			return
887		}
888		w.expirePendingLocked(req, now)
889	}
890	
891	// expirePendingLocked 将一笔待审批请求转为过期终态：决定时间记录本次处理
892	// 时刻，拒绝理由与审批账户保持为空，账本只追加一条关联使用账户与请求编号
893	// 的零金额过期记录。不冻结或退回费用，不改变任何余额与额度。必须在持锁
894	// 状态下调用。
895	func (w *Wallet) expirePendingLocked(req *request, now time.Time) {
896		req.state = RequestExpired
897		req.decidedAt = now
898		w.ledger = append(w.ledger, LedgerEntry{
899			Kind:      LedgerExpiration,
900			AccountID: req.accountID,
901			RequestID: req.requestID,
902			Reason:    "approval period expired",
903			At:        now,
904		})
905	}
906	
907	// settlePendingLocked 按等待截止时刻顺序（同截止时刻按使用账户、请求编号
908	// 排序）分别结清 reqs 中仍在待审批的请求，保证账本追加顺序确定。每笔请求
909	// 只按自己的等待截止时间判断：now 严格早于截止时间且 reject 非空时调用
910	// reject 进入拒绝终态（拒绝理由与审批账户由调用方决定），恰到或超过截止
911	// 时间的进入过期终态；已到期的与仍在等待的请求互不影响，不因共用会话或
912	// 策略而混同。两类处理都不冻结费用、不改变余额与额度。必须在持锁状态下
913	// 调用。
914	func (w *Wallet) settlePendingLocked(reqs []*request, now time.Time, reject func(req *request)) {
915		sortRequestsByDeadline(reqs, func(req *request) time.Time { return req.waitDeadline })
916		for _, req := range reqs {
917			if req.state != RequestPendingApproval {
918				continue
919			}
920			if now.Before(req.waitDeadline) {
921				if reject != nil {
922					reject(req)
923				}
924				continue
925			}
926			w.expirePendingLocked(req, now)
927		}
928	}
929	
930	// sortRequestsByDeadline 按 deadline 给出的截止时刻排序（同截止时刻按使用
931	// 账户、请求编号排序），供各类批量到期处理共用，保证账本追加顺序确定。
932	func sortRequestsByDeadline(reqs []*request, deadline func(req *request) time.Time) {
933		sort.SliceStable(reqs, func(i, j int) bool {
934			if di, dj := deadline(reqs[i]), deadline(reqs[j]); !di.Equal(dj) {
935				return di.Before(dj)
936			}
937			if reqs[i].accountID != reqs[j].accountID {
938				return reqs[i].accountID < reqs[j].accountID
939			}
940			return reqs[i].requestID < reqs[j].requestID
941		})
942	}
943	
944	// refreshReservedLocked 在持锁状态下检查单笔已预留请求是否已到最长预留
945	// 时长；截止时刻及之后转为“预留超时”终态并退回全额预留。必须在持锁状态
946	// 下调用。
947	func (w *Wallet) refreshReservedLocked(req *request, now time.Time) {
948		if req.state != RequestReserved || req.reserveDuration <= 0 {
949			return
950		}
951		if now.Before(req.reserveDeadline) {
952			return
953		}
954		w.expireReservationLocked(req, req.reserveDeadline)
955	}
956	
957	// expirePendingApprovalsLocked 惰性结清当前全部已到等待期限（含到期时刻）
958	// 的待审批请求，使它们进入过期终态并留下状态记录。必须在持锁状态下调用。
959	func (w *Wallet) expirePendingApprovalsLocked(now time.Time) {
960		pending := make([]*request, 0)
961		for _, req := range w.requests {
962			if req.state == RequestPendingApproval {
963				pending = append(pending, req)
964			}
965		}
966		w.settlePendingLocked(pending, now, nil)
967	}
968	
969	// expireReservationsLocked 惰性结清当前全部已到期（含到期时刻）的预留。
970	// 所有账户/余额/策略/请求/账本查询以及新申请、批准的资金检查入口都先调用
971	// 它，因此调用者无须逐笔取消即可看到已到期预留的释放结果。释放时间一律
972	// 记录为各请求自己的截止时刻，而不是处理时刻；账本按截止时刻顺序追加。
973	// 必须在持锁状态下调用。
974	func (w *Wallet) expireReservationsLocked(now time.Time) {
975		due := make([]*request, 0)
976		for _, req := range w.requests {
977			if req.state == RequestReserved && req.reserveDuration > 0 && !now.Before(req.reserveDeadline) {
978				due = append(due, req)
979			}
980		}
981		sortRequestsByDeadline(due, func(req *request) time.Time { return req.reserveDeadline })
982		for _, req := range due {
983			w.expireReservationLocked(req, req.reserveDeadline)
984		}
985	}
986	
987	// expireReservationLocked 将一笔已预留请求转为 RequestReservationExpired
988	// 终态：全额退回预估费用到出资账户可用余额，减少出资账户预留余额与该
989	// 策略的预留总额，不增加实际费用或已花费总额。账本增加一条出资账户的
990	// 全额退款记录和一条使用账户的零金额超时状态记录，均关联请求编号。
991	// 必须在持锁状态下调用。
992	func (w *Wallet) expireReservationLocked(req *request, deadline time.Time) {
993		payer := w.accounts[req.payerAccountID]
994		payer.reserved -= req.estimatedFee
995		payer.available += req.estimatedFee
996		if p := w.policies[req.policyID]; p != nil {
997			p.reservedTotal -= req.estimatedFee
998		}
999		req.state = RequestReservationExpired
1000		req.reserveExpiredAt = deadline
1001	
1002		w.ledger = append(w.ledger,
1003			LedgerEntry{
1004				Kind:      LedgerRefund,
1005				AccountID: payer.id,
1006				RequestID: req.requestID,
1007				Amount:    req.estimatedFee,
1008				Reason:    "refund reserved fee on reservation timeout",
1009				At:        deadline,
1010			},
1011			LedgerEntry{
1012				Kind:      LedgerReservationExpiration,
1013				AccountID: req.accountID,
1014				RequestID: req.requestID,
1015				Reason:    "reservation timed out before settlement",
1016				At:        deadline,
1017			},
1018		)
1019	}
1020	
1021	// reserveFeeLocked 一次性完成一笔费用的实际预留，供“普通申请直接受理”与
1022	// “待审批申请被出资账户批准”两条入口共用，避免资金、请求状态与账本分别
1023	// 维护：
1024	//   - 全部预估费用从出资账户可用余额转入预留余额，并计入策略的预留总额；
1025	//     策略已花费总额不变，费用始终由策略指定的出资账户承担；
1026	//   - 请求转为已预留，并以 reservedAt 作为实际预留时刻写入预留计时
1027	//     （启用最长预留时长时截止时刻为 reservedAt+时长，等待审批的时间不计
1028	//     入；未启用时截止时刻保持零值）；
1029	//   - 追加一条出资账户的预留记录，金额为预估费用全额，原因由调用方给出
1030	//     （直接受理与批准的说明不同）。
1031	//
1032	// 资金变化、请求转为已预留与预留记录在同一次持锁调用中完成，不会观察到
1033	// 只完成一部分的结果。审批路径的审批决定信息（决定时间、出资账户）与
1034	// 使用账户零金额批准记录由 Approve 在调用本函数后另行追加，直接受理则
1035	// 两者都不产生。必须在持锁状态下调用，且调用前已完成余额与额度检查。
1036	func (w *Wallet) reserveFeeLocked(p *policy, payer *account, req *request, reservedAt time.Time, reason string) {
1037		fee := req.estimatedFee
1038		payer.available -= fee
1039		payer.reserved += fee
1040		p.reservedTotal += fee
1041	
1042		req.state = RequestReserved
1043		req.reservedAt = reservedAt
1044		req.reserveDuration = p.maxReserveDuration
1045		if p.maxReserveDuration > 0 {
1046			req.reserveDeadline = reservedAt.Add(p.maxReserveDuration)
1047		}
1048	
1049		w.ledger = append(w.ledger, LedgerEntry{
1050			Kind:      LedgerReserve,
1051			AccountID: payer.id,
1052			RequestID: req.requestID,
1053			Amount:    fee,
1054			Reason:    reason,
1055			At:        reservedAt,
1056		})
1057	}
1058	
1059	// quotaWouldExceedLocked 判断在策略 p 上再计入 fee 后，共享累计合计是否
1060	// 严格超过累计上限，并返回计入前“现存预留 + 已结算实际费用”的合计（用于
1061	// 错误信息；该合计本身越过 int64 范围时返回 0）。现存预留、已结算实际费用
1062	// 与本次费用各自合法、但合计越过 int64 范围时 exceed 同样为 true：不能让
1063	// 求和回绕成小（或负）数后被当成额度充足。累计上限与单次上限仍允许取
1064	// int64 最大值，这里不缩小金额范围。必须在持锁状态下调用。
1065	func quotaWouldExceedLocked(p *policy, fee int64) (used int64, exceed bool) {
1066		used, ok := addInt64(p.reservedTotal, p.spentTotal)
1067		if !ok {
1068			return 0, true
1069		}
1070		total, ok := addInt64(used, fee)
1071		if !ok {
1072			return used, true
1073		}
1074		return used, total > p.maxTotal
1075	}
1076	
1077	// Request 查询某使用账户下的代付请求。待审批请求到期即转为过期终态，
1078	// 已预留请求到最长预留时长即转为预留超时终态，查询结果反映最新状态；
1079	// 超时释放时间记录的是截止时刻本身，而不是本次查询时刻。
1080	func (w *Wallet) Request(accountID, requestID string) (RequestView, error) {
1081		w.mu.Lock()
1082		defer w.mu.Unlock()
1083	
1084		req, _, err := w.lookupRequest(accountID, requestID)
1085		if err != nil {
1086			return RequestView{}, err
1087		}
1088		now := w.now()
1089		w.refreshPendingLocked(req, now)
1090		w.refreshReservedLocked(req, now)
1091		return req.view(), nil
1092	}
1093	
1094	// Ledger 返回全部账本记录的副本，按产生顺序排列。
1095	// 申请被拒绝的记录（Kind 为 LedgerRejection）也包含在内并带有原因。
1096	// 查询时已到期预留的自动退款与超时留痕也会在返回前补齐。
1097	func (w *Wallet) Ledger() []LedgerEntry {
1098		w.mu.Lock()
1099		defer w.mu.Unlock()
1100	
1101		w.expireReservationsLocked(w.now())
1102		out := make([]LedgerEntry, len(w.ledger))
1103		copy(out, w.ledger)
1104		return out
1105	}
1106	
1107	// AccountLedger 返回与指定账户相关的账本记录副本。
1108	//
1109	// 对出资账户返回预留、扣减、退回等资金变动记录；对待审批、批准、拒绝、
1110	// 取消、过期等状态记录（无金额变动），其 AccountID 为发起申请的使用
1111	// 账户，因此按使用账户查询可看到该请求的完整状态留痕。
1112	func (w *Wallet) AccountLedger(accountID string) []LedgerEntry {
1113		w.mu.Lock()
1114		defer w.mu.Unlock()
1115	
1116		w.expireReservationsLocked(w.now())
1117		var out []LedgerEntry
1118		for _, e := range w.ledger {
1119			if e.AccountID == accountID {
1120				out = append(out, e)
1121			}
1122		}
1123		return out
1124	}
1125	
1126	// lookupRequest 必须在持锁状态下调用。
1127	func (w *Wallet) lookupRequest(accountID, requestID string) (*request, *policy, error) {
1128		req, ok := w.requests[requestKey{accountID: accountID, requestID: requestID}]
1129		if !ok {
1130			return nil, nil, fmt.Errorf("%w: account %s request %s", ErrRequestNotFound, accountID, requestID)
1131		}
1132		return req, w.policies[req.policyID], nil
1133	}
1134	
1135	// reject 记录无需持锁快速校验阶段的拒绝（当前没有此类调用，保留对称接口）。
1136	func (w *Wallet) reject(in RequestInput, cause error) error {
1137		w.mu.Lock()
1138		defer w.mu.Unlock()
1139		w.appendRejection(in, w.now(), cause)
1140		return cause
1141	}
1142	
1143	// rejectLocked 在持锁状态下记录拒绝原因并原样返回错误。
1144	func (w *Wallet) rejectLocked(in RequestInput, at time.Time, cause error) error {
1145		w.appendRejection(in, at, cause)
1146		return cause
1147	}
1148	
1149	// appendRejection 必须在持锁状态下调用。拒绝记录不涉及金额变动，
1150	// 只记录使用账户、请求编号与具体原因。
1151	func (w *Wallet) appendRejection(in RequestInput, at time.Time, cause error) {
1152		w.ledger = append(w.ledger, LedgerEntry{
1153			Kind:      LedgerRejection,
1154			AccountID: in.AccountID,
1155			RequestID: in.RequestID,
1156			Reason:    cause.Error(),
1157			At:        at,
1158		})
1159	}
1160	
1161	func (a *account) view() AccountView {
1162		return AccountView{
1163			ID: a.id,
1164			Balances: Balances{
1165				Available: a.available,
1166				Reserved:  a.reserved,
1167			},
1168			CreatedAt: a.createdAt,
1169		}
1170	}
1171	
1172	func (s *session) view() SessionView {
1173		state := SessionActive
1174		if s.revoked {
1175			state = SessionRevoked
1176		}
1177		return SessionView{
1178			ID:        s.id,
1179			AccountID: s.accountID,
1180			DeviceID:  s.deviceID,
1181			ExpiresAt: s.expiresAt,
1182			State:     state,
1183			CreatedAt: s.createdAt,
1184		}
1185	}
1186	
1187	func (p *policy) view() PolicyView {
1188		ids := make([]string, 0, len(p.allowedAccounts))
1189		for id := range p.allowedAccounts {
1190			ids = append(ids, id)
1191		}
1192		return PolicyView{
1193			PolicySpec: PolicySpec{
1194				ID:                 p.id,
1195				PayerAccountID:     p.payerAccountID,
1196				AllowedAccountIDs:  ids,
1197				Operation:          p.operation,
1198				Payee:              p.payee,
1199				StartsAt:           p.startsAt,
1200				EndsAt:             p.endsAt,
1201				MaxPerRequest:      p.maxPerRequest,
1202				MaxTotal:           p.maxTotal,
1203				ApprovalThreshold:  p.approvalThreshold,
1204				ApprovalWait:       p.approvalWait,
1205				MaxReserveDuration: p.maxReserveDuration,
1206			},
1207			ReservedTotal:        p.reservedTotal,
1208			SpentTotal:           p.spentTotal,
1209			Deactivated:          p.deactivated,
1210			DeactivatedAt:        p.deactivatedAt,
1211			DeactivatorAccountID: p.deactivatorAccountID,
1212			DeactivateReason:     p.deactivateReason,
1213		}
1214	}
1215	
1216	func (r *request) view() RequestView {
1217		return RequestView{
1218			PolicyID:          r.policyID,
1219			RequestID:         r.requestID,
1220			AccountID:         r.accountID,
1221			PayerAccountID:    r.payerAccountID,
1222			Operation:         r.operation,
1223			Payee:             r.payee,
1224			EstimatedFee:      r.estimatedFee,
1225			ActualFee:         r.actualFee,
1226			State:             r.state,
1227			CreatedAt:         r.createdAt,
1228			SettledAt:         r.settledAt,
1229			WaitDeadline:      r.waitDeadline,
1230			ReservedAt:        r.reservedAt,
1231			ReserveDuration:   r.reserveDuration,
1232			ReserveDeadline:   r.reserveDeadline,
1233			ReserveExpiredAt:  r.reserveExpiredAt,
1234			DecidedAt:         r.decidedAt,
1235			ApproverAccountID: r.approverAccountID,
1236			RejectReason:      r.rejectReason,
1237		}
1238	}
1239

